def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {c: sum(row.count(c) for row in grid) for c in {x for row in grid for x in row}}
    bg = max(counts, key=counts.get)
    # Uniform full rows/columns are the partition lines; exclude the background.
    lines = []
    for c in counts:
        if c == bg:
            continue
        rows = [i for i, row in enumerate(grid) if all(x == c for x in row)]
        cols = [j for j in range(w) if all(grid[i][j] == c for i in range(h))]
        if rows or cols:
            lines.append((len(rows)+len(cols), c, rows, cols))
    if not lines:
        return [r[:] for r in grid]
    _, sep, rows, cols = max(lines)
    rb, cb = [-1] + rows + [h], [-1] + cols + [w]
    # The motif occupies the last row band and first column band; copy into matching cells.
    y0, y1, x0, x1 = rb[-2]+1, rb[-1], cb[0]+1, cb[1]
    tile = [grid[y][x0:x1] for y in range(y0,y1)]
    out = [r[:] for r in grid]
    for a in range(len(rb)-1):
